class Tests{static int n;static void C(bool x,string m){if(!x)throw new Exception(m);n++;}static void Main(){var asm=typeof(Health).Assembly;var t=asm.GetType("Ossastra.CharacterCore.EquipmentState");C(t!=null,"missing independent hand-instance authority");var kind=asm.GetType("Ossastra.CharacterCore.OffhandKind");object K(string s)=>Enum.Parse(kind,s);dynamic e=Activator.CreateInstance(t,new object[]{"a",100});dynamic other=Activator.CreateInstance(t,new object[]{"b",100});var right=(string)e.RightInstanceId;C(e.TryEquip((dynamic)K("Shield"),true),"equip shield");var shield=(string)e.LeftInstanceId;var token=Guid.NewGuid();C(e.Wear(token)&&e.Durability==99,"wear valid receipt");C(!e.Wear(token)&&e.Durability==99,"duplicate wear");C(e.TryEquip((dynamic)K("Bomb"),true)&&e.RightInstanceId==right&&e.LeftInstanceId!=shield,"independent hands");C(e.TryEquip((dynamic)K("Shield"),true)&&e.LeftInstanceId==shield&&e.Durability==99,"switch retains instance and wear");C(!e.TryEquip((dynamic)K("None"),false)&&e.LeftInstanceId==shield,"busy no equip");C(other.LeftInstanceId!=e.LeftInstanceId,"per-body ownership");var s=new StaminaState(100,.5,20);var drain=typeof(StaminaState).GetMethod("Drain");C(drain!=null,"continuous guard drain");C((bool)drain.Invoke(s,new object[]{6d,0d})&&s.Current==94,"guard drain exact");C(!(bool)drain.Invoke(s,new object[]{100d,0d})&&s.Current==0,"exhaust clears without negative");Console.WriteLine(n+" equipment/guard contracts passed");}}
